-- Table Plan: full database setup. Run once on a new, empty Supabase project.

-- ===== supabase/migrations/0001_init.sql =====
-- Table Plan M0/M1 schema. Prices in pence. RLS on everything user-owned.

create table public.ingredients (
  slug        text primary key,
  name        text not null,
  unit        text not null,
  cupboard    boolean not null default false,
  note        text,
  allergens   text[] not null default '{}',
  -- CoFID per 100 g/ml; null until verified (scraped/imported later)
  kcal_100    numeric, protein_100 numeric, carbs_100 numeric, fat_100 numeric,
  cofid_code  text,
  cofid_verified boolean not null default false
);

-- Retailer mapping, one product per ingredient per retailer (Morrisons-only at launch).
create table public.products (
  ingredient_slug text not null references public.ingredients(slug) on delete cascade,
  retailer        text not null default 'morrisons',
  name            text not null,
  price_pence     integer not null check (price_pence >= 0),
  pack_size       numeric not null check (pack_size > 0),
  slug            text not null,
  -- nightly price check (scripts/refresh-prices.ts)
  price_status    text not null default 'ok' check (price_status in ('ok','changed_big','out_of_stock','delisted','error')),
  checked_at      timestamptz,
  last_ok_at      timestamptz,
  updated_at      timestamptz not null default now(),
  primary key (ingredient_slug, retailer)
);

create table public.recipes (
  slug         text primary key,
  name         text not null,
  course       text not null check (course in ('breakfast','lunch','snack','dinner')),
  emoji        text,
  serves       integer not null default 1 check (serves >= 1),
  -- per portion
  kcal         integer not null, protein_g numeric not null, carbs_g numeric, fat_g numeric,
  method       text[] not null default '{}',
  allergens    text[] not null default '{}',   -- derived from ingredients by the importer
  status       text not null default 'draft' check (status in ('draft','verified','live')),
  source       text,
  macros_only  boolean not null default false,
  version      integer not null default 1,
  content_hash text,
  updated_at   timestamptz not null default now()
);

create table public.recipe_ingredients (
  recipe_slug     text not null references public.recipes(slug) on delete cascade,
  ingredient_slug text not null references public.ingredients(slug),
  qty             numeric not null,
  cupboard        boolean not null default false,
  primary key (recipe_slug, ingredient_slug)
);

create index recipe_ingredients_ingredient_idx on public.recipe_ingredients (ingredient_slug);

-- Edits snapshot the previous row, so saved plans can pin the version they used.
create table public.recipe_versions (
  recipe_slug text not null,
  version     integer not null,
  snapshot    jsonb not null,
  primary key (recipe_slug, version)
);

create or replace function public.snapshot_recipe() returns trigger language plpgsql set search_path = public as $$
begin
    on conflict do nothing;
  new.version = old.version + 1;
  new.updated_at = now();
  return new;
end $$;
create trigger recipes_snapshot before update on public.recipes
  for each row execute function public.snapshot_recipe();

-- One row per user; stats are optional (special-category health data).
create table public.profiles (
  user_id         uuid primary key references auth.users(id) on delete cascade,
  goal            text check (goal in ('lose','maintain','gain')),
  height_unit     text not null default 'cm' check (height_unit in ('cm','ftin')),
  weight_unit     text not null default 'kg' check (weight_unit in ('kg','stlb','lb')),
  height_cm       numeric,
  weight_kg       numeric,
  age             integer,
  sex             text check (sex in ('f','m')),
  activity        numeric not null default 1.375,
  skipped_stats   text[] not null default '{}',
  meals           jsonb not null,
  allergies       text[] not null default '{}',
  no_allergies    boolean not null default false,
  dislikes        text[] not null default '{}',
  liked_recipes   text[] not null default '{}',
  skipped_recipes text[] not null default '{}',
  onboarding_step text not null default 'goal',
  completed       boolean not null default false,
  -- weekly cycle (M5): weeks keyed by Monday, and reminder opt-in/shown state
  weeks           jsonb not null default '{}'::jsonb,
  reminders       jsonb not null default '{"on": false, "shown": []}'::jsonb,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);

alter table public.profiles enable row level security;
create policy "own profile read"   on public.profiles for select using ((select auth.uid()) = user_id);
create policy "own profile insert" on public.profiles for insert with check ((select auth.uid()) = user_id);
create policy "own profile update" on public.profiles for update using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "own profile delete" on public.profiles for delete using ((select auth.uid()) = user_id);

-- Catalogue tables: world-readable (live recipes only), writable only by the service role.
alter table public.ingredients enable row level security;
alter table public.products enable row level security;
alter table public.recipes enable row level security;
alter table public.recipe_ingredients enable row level security;
alter table public.recipe_versions enable row level security;
create policy "catalogue read" on public.ingredients for select using (true);
create policy "catalogue read" on public.products for select using (true);
create policy "live recipes read" on public.recipes for select using (status = 'live');
create policy "live recipe lines read" on public.recipe_ingredients for select
  using (exists (select 1 from public.recipes r where r.slug = recipe_slug and r.status = 'live'));

create or replace function public.touch_updated_at() returns trigger language plpgsql set search_path = public as $$
begin new.updated_at = now(); return new; end $$;
create trigger profiles_touch before update on public.profiles
  for each row execute function public.touch_updated_at();


-- ===== supabase/migrations/0002_subscriptions.sql =====
-- Subscription state mirrored from Stripe webhooks. Users can read their own row; only the service role writes.
create table public.subscriptions (
  user_id              uuid primary key references auth.users(id) on delete cascade,
  stripe_customer_id   text unique,
  status               text not null default 'none' check (status in ('none','trialing','active','past_due','canceled')),
  plan                 text check (plan in ('yearly','monthly')),
  trial_ends_at        timestamptz,
  current_period_end   timestamptz,
  cancel_at_period_end boolean not null default false,
  updated_at           timestamptz not null default now()
);
alter table public.subscriptions enable row level security;
create policy "own subscription read" on public.subscriptions for select using ((select auth.uid()) = user_id);
-- no insert/update/delete policies: webhooks use the service role, which bypasses RLS.

-- Webhook idempotency: Stripe retries, so remember which events were processed.
create table public.stripe_events (id text primary key, received_at timestamptz not null default now());
alter table public.stripe_events enable row level security;


-- ===== supabase/migrations/0003_beta.sql =====
-- Private beta: waitlist, invites, feedback. All three are written by server routes with the service role,
-- so RLS is on with no policies except feedback (users may insert their own).
create table public.waitlist (
  id          uuid primary key default gen_random_uuid(),
  email       text not null unique check (email = lower(email)),
  source      text not null default 'site',
  consent_at  timestamptz not null,      -- when they agreed to be emailed (UK GDPR)
  created_at  timestamptz not null default now(),
  invited_at  timestamptz
);
alter table public.waitlist enable row level security;

create table public.invites (
  code         text primary key check (code = upper(code) and length(code) = 12),  -- stored without dashes
  waitlist_id  uuid references public.waitlist(id),
  email        text,                       -- who redeemed it
  created_at   timestamptz not null default now(),
  redeemed_at  timestamptz
);
alter table public.invites enable row level security;
create index invites_waitlist_idx on public.invites (waitlist_id);

-- Atomic single-use redemption: returns true only for the one request that wins.
create or replace function public.redeem_invite(p_code text, p_email text) returns boolean
language sql security definer set search_path = public as $$
  with u as (
    update public.invites set email = lower(p_email), redeemed_at = now()
    where code = upper(p_code) and redeemed_at is null returning 1
  ) select exists (select 1 from u);
$$;
revoke all on function public.redeem_invite(text, text) from public, anon, authenticated;

create table public.feedback (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid references auth.users(id) on delete set null,
  message    text not null check (length(message) between 3 and 2000),
  page       text,
  created_at timestamptz not null default now()
);
alter table public.feedback enable row level security;
create index feedback_user_idx on public.feedback (user_id);
create policy "own feedback insert" on public.feedback for insert with check ((select auth.uid()) = user_id);


-- ===== supabase/migrations/0004_nutrition_budget.sql =====
-- Computed nutrition + budget tiers (100-meal bank).
-- Ingredients: how each per-100 value was sourced, unit weights, and cupboard pricing.
alter table public.ingredients
  add column if not exists grams_per_unit numeric,
  add column if not exists negligible boolean not null default false,
  add column if not exists cupboard_price_pence integer,
  add column if not exists cupboard_price_grams numeric,
  add column if not exists nutrition_basis text check (nutrition_basis in ('cofid', 'label')),
  add column if not exists nutrition_note text;

-- Recipes: marginal cost per portion (pence) and its low/medium/high tier, computed by the importer.
alter table public.recipes
  add column if not exists cost_pence integer,
  add column if not exists budget text check (budget in ('low', 'medium', 'high'));

-- Profiles: spend cap for auto-picked weeks. low = cheapest-tier meals, medium = up to mid-priced, high = no cap.
alter table public.profiles
  add column if not exists budget text not null default 'medium' check (budget in ('low', 'medium', 'high'));


-- ===== supabase/migrations/0005_recipe_images.sql =====
-- Meal header photos: the files are served from /meals/<slug>-<width>.webp; the database holds the alt text and the
-- placeholder colour (the photo's average) so any client can render a placeholder before the file arrives.
alter table public.recipes
  add column if not exists image_alt text,
  add column if not exists image_colour text check (image_colour ~ '^#[0-9a-f]{6}$');


